 LinearLayout root,actions,results;TextView status,meter,title;Stage stage;Vu vu;ProgressBar progress;Button record,play,cancelButton;volatile boolean cancelled,busy,micRunning,recording;AudioRecord mic;Thread micThread;MediaPlayer player;File pending;boolean pendingShare,ready,destroyed,resumed;long micStart;double latestDb=-100;String characterName="Mon personnage";HashSet<String> muteErrors=new HashSet<>(),hideErrors=new HashSet<>();
