 interface Input extends AutoCloseable {int read(short[] b,int offset,int count);void close();}
 interface InputFactory {Input open()throws Exception;}
 InputFactory inputFactory=()->{int min=AudioRecord.getMinBufferSize(16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);final AudioRecord input=new AudioRecord(MediaRecorder.AudioSource.VOICE_RECOGNITION,16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,Math.max(min,4096));try{if(input.getState()!=AudioRecord.STATE_INITIALIZED)throw new IOException("Le micro n’est pas disponible.");input.startRecording();if(input.getRecordingState()!=AudioRecord.RECORDSTATE_RECORDING)throw new IOException("Le micro n’a pas démarré.");return new Input(){public int read(short[] b,int offset,int count){return input.read(b,offset,count);}public void close(){try{input.stop();}catch(Exception ignored){}input.release();}};}catch(Exception e){input.release();throw e;}};
 boolean hasMicPermission(){return checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED;}
 void refreshLive(){if(!resumed||destroyed||!ready||busy||player!=null||recording||micFailed)return;if(!hasMicPermission()){if(!permissionAsked){permissionAsked=true;requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},20);}return;}if(wantedMic==0)requestMic(1);else if(!micRunning){ui.removeCallbacks(reconcileMic);ui.post(reconcileMic);}}
 void requestMic(int mode){wantedMic=mode;if(micRunning&&recording==(mode==2)&&mode!=0)return;micRunning=false;ui.removeCallbacks(reconcileMic);ui.post(reconcileMic);}
 final Runnable reconcileMic=new Runnable(){public void run(){if(destroyed||!resumed||busy||player!=null||wantedMic==0)return;if(micThread!=null){ui.postDelayed(this,30);return;}startMic(wantedMic==2);}};

