 public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences(preferenceFile,0);settings.gate=prefs.getFloat("gate",-32);settings.low=prefs.getFloat("low",-40);settings.high=prefs.getFloat("high",-6);settings.smooth=prefs.getInt("smooth",220);settings.whisper=prefs.getInt("whisper",50);settings.loud=prefs.getInt("loud",90);if(prefs.contains("gate")){settings.normalDb=Double.NaN;settings.loudDb=Double.NaN;}if(prefs.contains("normalDb"))settings.normalDb=prefs.getFloat("normalDb",0);if(prefs.contains("loudDb"))settings.loudDb=prefs.getFloat("loudDb",0);audio.gate=prefs.getBoolean("audioGate",true);audio.music=prefs.getFloat("musicVolume",.80f);audio.radio=prefs.getBoolean("radio",false);audio.reduction=prefs.getFloat("duckReduction",19);audio.attack=prefs.getInt("duckAttack",35);audio.release=prefs.getInt("duckRelease",450);audio.gateDb=prefs.getFloat("microGateDb",-40);audio.gateAttack=prefs.getInt("microGateAttack",10);audio.gateHold=prefs.getInt("microGateHold",300);audio.gateRelease=prefs.getInt("microGateRelease",1000);backdrop.color=prefs.getInt("backgroundColor",0xfff2effa);build();task("Chargement des personnages",()->{backdrop.load(this,prefs.getString("backgroundId",""));ArrayList<Packs.Pack> list=Packs.list(this);if(list.isEmpty())throw new IOException("Aucun personnage disponible.");Packs.Pack chosen=list.get(0);String id=prefs.getString("pack","");for(Packs.Pack p:list)if(p.id.equals(id))chosen=p;Packs.load(this,chosen);final Packs.Pack loaded=chosen;ui.post(()->{pack=loaded;title.setText(pack.name);ready=true;stage.invalidate();status.setText("Choisis un personnage, puis parle ou importe un audio.");});});}
